          "code": "import numpy as np\n\nrng = np.random.default_rng(291)\n\n# -----------------------------------------------------------------------------\n# First-Principles NumPy: Balanced Stratified Group K-Fold + Efek Acak Entitas u_g\n# Simulasi 180 pasien (masing-masing 4-8 kunjungan) -> total 1.073 observasi\n# Model data sejati: Y_{g,j} = 0.75 * x_{g,j} + u_g + eps_{g,j}\n# -----------------------------------------------------------------------------\nn_groups = 180\nvisits_per_group = rng.integers(4, 9, size=n_groups)\ngroups = np.repeat(np.arange(n_groups), visits_per_group)\nn_samples = len(groups)\n\n# Efek laten pasien (u_g) jauh lebih dominan dibanding noise kunjungan (eps)\nu_group_true = rng.normal(0.0, 2.0, size=n_groups)\nx_clin = rng.normal(0.0, 1.0, size=n_samples)\neps = rng.normal(0.0, 0.55, size=n_samples)\ny_cont = 0.75 * x_clin + u_group_true[groups] + eps\ny_bin = (y_cont > np.percentile(y_cont, 78)).astype(int)\n\n# Sidik jari identitas pasien murni (independen dari risiko laten u_g, konstan antar kunjungan!)\nfp1 = rng.normal(0.0, 2.0, size=n_groups)[groups] + rng.normal(0.0, 0.04, size=n_samples)\nfp2 = rng.normal(0.0, 2.0, size=n_groups)[groups] + rng.normal(0.0, 0.04, size=n_samples)\nX = np.column_stack([x_clin, fp1, fp2])\n\ndef stratified_group_kfold_scratch(\n    y: np.ndarray, grp: np.ndarray, n_splits: int = 5\n) -> list[tuple[np.ndarray, np.ndarray]]:\n    uniq_g = np.unique(grp)\n    g_stats = []\n    for g in uniq_g:\n        m = grp == g\n        g_stats.append((int(g), int(y[m].sum()), int(m.sum())))\n    # Urutkan menurun menurut jumlah positif lalu ukuran grup (greedy stratified bin-packing)\n    g_stats.sort(key=lambda t: (t[1], t[2]), reverse=True)\n\n    target_pos_per_fold = float(y.sum()) / n_splits\n    target_tot_per_fold = float(len(y)) / n_splits\n    fold_pos = np.zeros(n_splits, dtype=float)\n    fold_tot = np.zeros(n_splits, dtype=float)\n    fold_groups: list[list[int]] = [[] for _ in range(n_splits)]\n\n    for g_id, n_p, n_t in g_stats:\n        best_f, best_cost = 0, float(\"inf\")\n        for f in range(n_splits):\n            # Fungsi biaya cembung murni dari 0: menyeimbangkan beban positif & total baris di seluruh fold\n            pos_load = (fold_pos[f] + n_p) / max(1.0, target_pos_per_fold)\n            tot_load = (fold_tot[f] + n_t) / max(1.0, target_tot_per_fold)\n            cost = 2.0 * (pos_load ** 2) + 1.5 * (tot_load ** 2)\n            if cost < best_cost:\n                best_cost = cost\n                best_f = f\n        fold_groups[best_f].append(g_id)\n        fold_pos[best_f] += n_p\n        fold_tot[best_f] += n_t\n\n    folds = []\n    for f in range(n_splits):\n        val_mask = np.isin(grp, fold_groups[f])\n        val_idx = np.where(val_mask)[0]\n        tr_idx = np.where(~val_mask)[0]\n        folds.append((tr_idx, val_idx))\n    return folds\n\nsgkf_folds = stratified_group_kfold_scratch(y_bin, groups, n_splits=5)\n\nprint(f\"=== Audit StratifiedGroupKFold First-Principles (N={n_samples}, G={n_groups}, pi={y_bin.mean():.3f}) ===\")\nfor k, (tr, va) in enumerate(sgkf_folds, start=1):\n    overlap = set(groups[tr]).intersection(set(groups[va]))\n    assert len(overlap) == 0, f\"Group leakage detected in fold {k}!\"\n    print(\n        f\"Fold {k} | n_train={len(tr):4d} | n_val={len(va):3d} | \"\n        f\"val_groups={len(np.unique(groups[va])):2d} | val_pi={y_bin[va].mean():.4f} | group_overlap={len(overlap)}\"\n    )\n\n# Bukti analitis dekomposisi MSE dengan 1-NN pada ruang fitur sidik jari\ndef knn1_mse(X_mat: np.ndarray, y_vec: np.ndarray, folds: list[tuple[np.ndarray, np.ndarray]]) -> float:\n    sq_errs = []\n    for tr, va in folds:\n        d2 = np.sum((X_mat[va, None, :] - X_mat[None, tr, :]) ** 2, axis=2)\n        nn = np.argmin(d2, axis=1)\n        preds = y_vec[tr][nn]\n        sq_errs.append((y_vec[va] - preds) ** 2)\n    return float(np.mean(np.concatenate(sq_errs)))\n\nperm = rng.permutation(n_samples)\nrand_folds = []\nchunks = np.array_split(perm, 5)\nfor k in range(5):\n    va = chunks[k]\n    tr = np.concatenate([chunks[j] for j in range(5) if j != k])\n    rand_folds.append((tr, va))\n\nmse_rand = knn1_mse(X, y_cont, rand_folds)\nmse_grp = knn1_mse(X, y_cont, sgkf_folds)\nprint(\"\\n=== Dampak Efek Laten Pasien u_g pada Estimasi MSE (1-NN) ===\")\nprint(f\"Random KFold (BOCOR ENTITAS)      : MSE = {mse_rand:.4f}  (hanya menaksir noise kunjungan!)\")\nprint(f\"StratifiedGroupKFold (JUJUR)      : MSE = {mse_grp:.4f}  (menangkap galat generalisasi pasien baru!)\")\nprint(f\"Rasio Ilusi Under-Estimation MSE  : {mse_grp / mse_rand:.2f}x lebih tinggi di pasien baru!\")",
