          "title": "Production Audit: Temporal & Rolling-Window Leakage — KFold(shuffle=True) vs TimeSeriesSplit(gap=0 vs gap=14)",
          "language": "python",
          "filename": "29_1_temporal_rolling_leakage_audit.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import GradientBoostingRegressor\nfrom sklearn.metrics import r2_score, root_mean_squared_error\nfrom sklearn.model_selection import KFold, TimeSeriesSplit\n\nrng = np.random.default_rng(2913)\n\n# -----------------------------------------------------------------------------\n# Production Audit: Temporal & Rolling-Window Leakage pada Deret Waktu Transaksi\n# T = 800 hari dengan rezim makro AR(1) (phi=0.97) + fitur rolling 14-hari\n# Target: volume transaksi 7 hari ke depan (horizon H = 7)\n# -----------------------------------------------------------------------------\nT = 800\nregime = np.zeros(T)\nfor t in range(1, T):\n    regime[t] = 0.97 * regime[t - 1] + rng.normal(0.0, 0.35)\n\n# Volume harian dipengaruhi rezim makro + pola mingguan + noise harian\nday_of_week = np.sin(2.0 * np.pi * np.arange(T) / 7.0)\ndaily_vol = 50.0 + 6.5 * regime + 3.0 * day_of_week + rng.normal(0.0, 2.2, size=T)\n\n# Buat fitur masa lalu yang sah (lag-1, rolling mean 14d, rolling std 14d, momentum)\nwin = 14\nhorizon = 7\nrows_X, rows_y = [], []\nfor t in range(win, T - horizon):\n    past = daily_vol[t - win : t]\n    rows_X.append([\n        daily_vol[t - 1],\n        float(np.mean(past)),\n        float(np.std(past)),\n        float(daily_vol[t - 1] - np.mean(past)),\n        day_of_week[t + horizon],\n    ])\n    rows_y.append(daily_vol[t + horizon])\n\nX_ts = np.asarray(rows_X, dtype=float)\ny_ts = np.asarray(rows_y, dtype=float)\n\ndef eval_splitter(name: str, splitter, expected_gap: int | None = None) -> None:\n    r2s, rmses = [], []\n    min_observed_gap = 10**9\n    for tr, va in splitter.split(X_ts):\n        if expected_gap is not None:\n            gap_now = int(va.min() - tr.max() - 1)\n            min_observed_gap = min(min_observed_gap, gap_now)\n            assert gap_now >= expected_gap, f\"Temporal gap violation: {gap_now} < {expected_gap}\"\n        reg = GradientBoostingRegressor(n_estimators=50, max_depth=4, random_state=42)\n        reg.fit(X_ts[tr], y_ts[tr])\n        pred = reg.predict(X_ts[va])\n        r2s.append(r2_score(y_ts[va], pred))\n        rmses.append(root_mean_squared_error(y_ts[va], pred))\n    gap_str = f\"min_gap={min_observed_gap:2d} hari\" if expected_gap is not None else \"ACAK (BOCOR!)\"\n    print(f\"{name:32s} | {gap_str:15s} | Mean R2 = {np.mean(r2s):+.4f} | Mean RMSE = {np.mean(rmses):.4f}\")\n\nprint(f\"=== Audit Temporal Leakage Deret Waktu (N={len(y_ts)} hari, Horizon H={horizon}, Rolling={win}) ===\")\neval_splitter(\"1. KFold(shuffle=True) [BOCOR]\", KFold(n_splits=5, shuffle=True, random_state=42))\neval_splitter(\"2. TimeSeriesSplit(gap=0)\", TimeSeriesSplit(n_splits=5, gap=0), expected_gap=0)\neval_splitter(\"3. TimeSeriesSplit(gap=14)\", TimeSeriesSplit(n_splits=5, gap=14), expected_gap=14)",
