          "filename": "29_2_purged_embargoed_kfold_scratch.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(292)\n\n# -----------------------------------------------------------------------------\n# First-Principles NumPy: Purged & Embargoed K-Fold (Lopez de Prado, AFML Ch. 7)\n# Mendukung interval label heterogen [t0_i, t1_i] (seperti Triple-Barrier Method)\n# -----------------------------------------------------------------------------\nN = 500\nt0 = np.arange(N, dtype=int)\n# Horizon label bervariasi antara 8 hingga 24 bar (variable holding period!)\nhorizons = rng.integers(8, 25, size=N)\nt1 = np.minimum(t0 + horizons, N - 1)\n\ndef purged_embargoed_kfold_split(\n    t0_arr: np.ndarray, t1_arr: np.ndarray, n_splits: int = 5, embargo_pct: float = 0.03\n) -> list[dict]:\n    n = len(t0_arr)\n    embargo_bars = int(np.ceil(n * embargo_pct))\n    indices = np.arange(n)\n    test_blocks = np.array_split(indices, n_splits)\n    reports = []\n\n    for fold_id, test_idx in enumerate(test_blocks, start=1):\n        test_t0_min = int(t0_arr[test_idx[0]])\n        test_t1_max = int(t1_arr[test_idx].max())\n\n        cand_train = np.setdiff1d(indices, test_idx, assume_unique=True)\n\n        # 1. PURGING: hapus setiap observasi latih yang interval [t0_i, t1_i]\n        #    menabrak rentang label uji [test_t0_min, test_t1_max]\n        overlap_mask = (t0_arr[cand_train] <= test_t1_max) & (t1_arr[cand_train] >= test_t0_min)\n        purged_idx = cand_train[overlap_mask]\n        after_purge = cand_train[~overlap_mask]\n\n        # 2. EMBARGO (AFML Ch. 7.4.2): hapus pita karantina Delta_e tepat SETELAH\n        #    ujung informasi label uji (test_t1_max < t0_i <= test_t1_max + Delta_e)\n        embargo_limit = test_t1_max + embargo_bars\n        embargo_mask = (t0_arr[after_purge] > test_t1_max) & (t0_arr[after_purge] <= embargo_limit)\n        embargoed_idx = after_purge[embargo_mask]\n        clean_train = after_purge[~embargo_mask]\n\n        # Verifikasi keras: ZERO interval overlap & ZERO pelanggaran pita embargo!\n        if len(clean_train) > 0:\n            still_overlap = np.any(\n                (t0_arr[clean_train] <= test_t1_max) & (t1_arr[clean_train] >= test_t0_min)\n            )\n            assert not still_overlap, f\"Purging failed on fold {fold_id}!\"\n            right_side = clean_train[t0_arr[clean_train] > test_t1_max]\n            if len(right_side) > 0:\n                assert t0_arr[right_side].min() > embargo_limit, f\"Embargo failed on fold {fold_id}!\"\n\n        reports.append({\n            \"fold\": fold_id,\n            \"test_range\": (int(test_idx[0]), int(test_idx[-1])),\n            \"test_t1_max\": test_t1_max,\n            \"n_test\": len(test_idx),\n            \"n_purged\": len(purged_idx),\n            \"n_embargoed\": len(embargoed_idx),\n            \"n_train_clean\": len(clean_train),\n        })\n    return reports\n\nembargo_pct = 0.03\nreps = purged_embargoed_kfold_split(t0, t1, n_splits=5, embargo_pct=embargo_pct)\nprint(f\"=== Purged & Embargoed 5-Fold (N={N}, Horizon in [8, 24], Embargo={int(np.ceil(N*embargo_pct))} bar pasca-t1_max) ===\")\nfor r in reps:\n    lo, hi = r[\"test_range\"]\n    print(\n        f\"Fold {r['fold']} | Test=[{lo:3d}..{hi:3d}] (t1_max={r['test_t1_max']:3d}) | \"\n        f\"Purged={r['n_purged']:2d} | Embargoed={r['n_embargoed']:2d} | CleanTrain={r['n_train_clean']:3d} | Overlap=0\"\n    )",
          "expectedOutput": "=== Purged & Embargoed 5-Fold (N=500, Horizon in [8, 24], Embargo=15 bar pasca-t1_max) ===\nFold 1 | Test=[  0.. 99] (t1_max=120) | Purged=21 | Embargoed=15 | CleanTrain=364 | Overlap=0\nFold 2 | Test=[100..199] (t1_max=218) | Purged=37 | Embargoed=15 | CleanTrain=348 | Overlap=0\nFold 3 | Test=[200..299] (t1_max=316) | Purged=32 | Embargoed=15 | CleanTrain=353 | Overlap=0\nFold 4 | Test=[300..399] (t1_max=417) | Purged=33 | Embargoed=15 | CleanTrain=352 | Overlap=0\nFold 5 | Test=[400..499] (t1_max=499) | Purged=17 | Embargoed= 0 | CleanTrain=383 | Overlap=0",
          "actualOutput": "=== Purged & Embargoed 5-Fold (N=500, Horizon in [8, 24], Embargo=15 bar pasca-t1_max) ===\nFold 1 | Test=[  0.. 99] (t1_max=120) | Purged=21 | Embargoed=15 | CleanTrain=364 | Overlap=0\nFold 2 | Test=[100..199] (t1_max=218) | Purged=37 | Embargoed=15 | CleanTrain=348 | Overlap=0\nFold 3 | Test=[200..299] (t1_max=316) | Purged=32 | Embargoed=15 | CleanTrain=353 | Overlap=0\nFold 4 | Test=[300..399] (t1_max=417) | Purged=33 | Embargoed=15 | CleanTrain=352 | Overlap=0\nFold 5 | Test=[400..499] (t1_max=499) | Purged=17 | Embargoed= 0 | CleanTrain=383 | Overlap=0",
          "explanation": "Mengimplementasikan algoritma Purging & Embargoing (AFML Ch. 7.4.2) dari nol untuk 500 observasi berhorizon variabel [8, 24] bar: membuang 17-37 baris overlap per fold dan tepat 15 baris embargo pasca-t1_test_max pada Fold 1-4 dengan assertion keras Overlap=0.",
