          "id": "code-ml-29-3-ch29_3_scratch",
          "title": "First-Principles NumPy: Bukti Monte Carlo Winner's Curse Pure Noise (Non-Nested 0.619 vs Nested 0.458)",
          "language": "python",
          "filename": "29_3_winners_curse_nested_scratch.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(293)\n\n# -----------------------------------------------------------------------------\n# First-Principles NumPy: Bukti Monte Carlo Winner's Curse (Non-Nested vs Nested CV)\n# Data PURE NOISE: N = 120, d = 80 fitur acak, y ~ Bernoulli(0.5) -> AUROC sejati = 0.5000!\n# Menjelajahi M = 60 kandidat proyeksi/subset fitur (mirip pencarian 60 trial Optuna)\n# melintasi 8 replikasi independen untuk mengukur ekspektasi bias optimistik!\n# -----------------------------------------------------------------------------\ndef fast_auc(y_true: np.ndarray, scores: np.ndarray) -> float:\n    order = np.argsort(scores, kind=\"mergesort\")\n    ranks = np.empty_like(order, dtype=float)\n    ranks[order] = np.arange(1, len(scores) + 1, dtype=float)\n    pos = y_true == 1\n    n1 = int(pos.sum())\n    n0 = len(y_true) - n1\n    return float((ranks[pos].sum() - n1 * (n1 + 1) / 2.0) / (n1 * n0))\n\ndef make_stratified_folds(y_vec: np.ndarray, k: int, r: np.random.Generator) -> list[tuple[np.ndarray, np.ndarray]]:\n    p_idx = r.permutation(np.where(y_vec == 1)[0])\n    n_idx = r.permutation(np.where(y_vec == 0)[0])\n    p_chunks = np.array_split(p_idx, k)\n    n_chunks = np.array_split(n_idx, k)\n    return [\n        (np.setdiff1d(np.arange(len(y_vec)), np.concatenate([p_chunks[i], n_chunks[i]]), assume_unique=True),\n         np.concatenate([p_chunks[i], n_chunks[i]]))\n        for i in range(k)\n    ]\n\nN, d, M = 120, 80, 60\nn_trials = 8\nnon_nested_bests, nested_outers = [], []\n\ncand_specs = [(rng.choice(d, size=int(rng.integers(3, 12)), replace=False), float(rng.choice([0.1, 1.0, 10.0]))) for _ in range(M)]\n\nfor trial in range(n_trials):\n    X = rng.normal(0.0, 1.0, size=(N, d))\n    y = np.r_[np.ones(N // 2, dtype=int), np.zeros(N // 2, dtype=int)]\n    rng.shuffle(y)\n    outer_folds = make_stratified_folds(y, k=5, r=rng)\n\n    def eval_cand(X_sub: np.ndarray, y_sub: np.ndarray, folds, cols, lam: float) -> float:\n        aucs = []\n        for tr, va in folds:\n            Xtr, Xva = X_sub[tr][:, cols], X_sub[va][:, cols]\n            mu = Xtr.mean(axis=0)\n            Xc = Xtr - mu\n            yc = y_sub[tr] - y_sub[tr].mean()\n            w = np.linalg.solve(Xc.T @ Xc + lam * np.eye(len(cols)), Xc.T @ yc)\n            aucs.append(fast_auc(y_sub[va], (Xva - mu) @ w))\n        return float(np.mean(aucs))\n\n    nn_scores = [eval_cand(X, y, outer_folds, cols, lam) for cols, lam in cand_specs]\n    non_nested_bests.append(max(nn_scores))\n\n    out_aucs = []\n    for tr_out, va_out in outer_folds:\n        in_folds = make_stratified_folds(y[tr_out], k=4, r=rng)\n        in_scores = [eval_cand(X[tr_out], y[tr_out], in_folds, cols, lam) for cols, lam in cand_specs]\n        best_cols, best_lam = cand_specs[int(np.argmax(in_scores))]\n        Xtr, Xva = X[tr_out][:, best_cols], X[va_out][:, best_cols]\n        mu = Xtr.mean(axis=0)\n        Xc = Xtr - mu\n        yc = y[tr_out] - y[tr_out].mean()\n        w = np.linalg.solve(Xc.T @ Xc + best_lam * np.eye(len(best_cols)), Xc.T @ yc)\n        out_aucs.append(fast_auc(y[va_out], (Xva - mu) @ w))\n    nested_outers.append(float(np.mean(out_aucs)))\n\nprint(f\"=== Monte Carlo Winner's Curse pada Pure Noise ({n_trials} replikasi, N={N}, d={d}, M={M}, True=0.5000) ===\")\nprint(f\"1. Non-Nested CV best_score_ [BIASA OPTIMIS] : {np.mean(non_nested_bests):.4f} +/- {np.std(non_nested_bests):.4f} (Bias = {np.mean(non_nested_bests) - 0.5:+.4f}!)\")\nprint(f\"2. Nested CV Outer Score     [JUJUR]         : {np.mean(nested_outers):.4f} +/- {np.std(nested_outers):.4f} (Bias = {np.mean(nested_outers) - 0.5:+.4f})\")",
          "expectedOutput": "=== Monte Carlo Winner's Curse pada Pure Noise (8 replikasi, N=120, d=80, M=60, True=0.5000) ===\n1. Non-Nested CV best_score_ [BIASA OPTIMIS] : 0.6194 +/- 0.0305 (Bias = +0.1194!)\n2. Nested CV Outer Score     [JUJUR]         : 0.4582 +/- 0.0639 (Bias = -0.0418)",
          "actualOutput": "=== Monte Carlo Winner's Curse pada Pure Noise (8 replikasi, N=120, d=80, M=60, True=0.5000) ===\n1. Non-Nested CV best_score_ [BIASA OPTIMIS] : 0.6194 +/- 0.0305 (Bias = +0.1194!)\n2. Nested CV Outer Score     [JUJUR]         : 0.4582 +/- 0.0639 (Bias = -0.0418)",
