          "language": "python",
          "filename": "29_3_sklearn_nested_cv_audit.py",
          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.feature_selection import SelectKBest, f_classif\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import GridSearchCV, StratifiedKFold, cross_val_score, train_test_split\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.svm import SVC\n\n# -----------------------------------------------------------------------------\n# Scikit-Learn 1.9: Nested CV (5x4) vs Non-Nested GridSearchCV.best_score_\n# Dataset dimensi tinggi (N_dev=240, d=120, hanya 3 fitur informatif ber-noise tinggi)\n# dengan ruang pencarian 36 konfigurasi -> memperlihatkan bias optimis best_score_!\n# -----------------------------------------------------------------------------\nX_all, y_all = make_classification(\n    n_samples=1240,\n    n_features=120,\n    n_informative=3,\n    n_redundant=2,\n    class_sep=0.55,\n    flip_y=0.14,\n    random_state=2938,\n)\nX_dev, X_lock, y_dev, y_lock = train_test_split(\n    X_all, y_all, test_size=1000, stratify=y_all, random_state=42\n)\n\npipe = Pipeline([\n    (\"scaler\", StandardScaler()),\n    (\"sel\", SelectKBest(f_classif)),\n    (\"svc\", SVC(kernel=\"rbf\", random_state=42)),\n])\n\nparam_grid = {\n    \"sel__k\": [3, 6, 15, 40],\n    \"svc__C\": [0.1, 1.0, 10.0],\n    \"svc__gamma\": [0.005, 0.05, 0.3],\n}\n\ninner_cv = StratifiedKFold(n_splits=3, shuffle=True, random_state=42)\nouter_cv = StratifiedKFold(n_splits=4, shuffle=True, random_state=99)\n\n# 1. Non-Nested: melaporkan best_score_ langsung dari GridSearchCV atas 36 kombinasi\ngs = GridSearchCV(pipe, param_grid=param_grid, cv=inner_cv, scoring=\"roc_auc\", refit=True)\ngs.fit(X_dev, y_dev)\nnon_nested_best = float(gs.best_score_)\n\n# 2. Nested CV: mengevaluasi keseluruhan PROSEDUR GridSearchCV di dalam outer_cv\nnested_scores = cross_val_score(\n    GridSearchCV(pipe, param_grid=param_grid, cv=inner_cv, scoring=\"roc_auc\"),\n    X_dev,\n    y_dev,\n    cv=outer_cv,\n    scoring=\"roc_auc\",\n)\n\n# 3. Evaluasi model final (refit pada 100% X_dev) di Locked Out-of-Sample Test Set (N=1.000)\nlocked_auc = float(roc_auc_score(y_lock, gs.best_estimator_.decision_function(X_lock)))\n\nprint(f\"=== Audit Nested CV vs GridSearchCV.best_score_ (N_dev={len(y_dev)}, N_lock={len(y_lock)}, |Grid|=36) ===\")\nprint(f\"Best Params (Refit 100% X_dev)             : {gs.best_params_}\")\nprint(f\"1. Non-Nested GridSearchCV.best_score_     : {non_nested_best:.4f}  (Bias vs Locked = {non_nested_best - locked_auc:+.4f})\")\nprint(f\"2. Nested CV (4 Outer x 3 Inner) [JUJUR]   : {nested_scores.mean():.4f} +/- {nested_scores.std():.4f}  (Bias vs Locked = {nested_scores.mean() - locked_auc:+.4f})\")\nprint(f\"3. Locked Out-of-Sample Test Set [REALITA] : {locked_auc:.4f}\")",
