          "code": "import numpy as np\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.inspection import permutation_importance\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold, cross_val_predict\n\nrng = np.random.default_rng(2933)\n\n# -----------------------------------------------------------------------------\n# Production Audit: Adversarial Validation Gate + Permutation Importance Forensics\n# Membedakan z=0 (Train, n=700) vs z=1 (Produksi/Test, n=700) pada 8 fitur\n# Injeksi 2 bug nyata: (1) order_seq_id naik monotonik; (2) income_bug berubah skala/null!\n# -----------------------------------------------------------------------------\nn_tr, n_te = 700, 700\nfeat_names = [\n    \"age\", \"tenure_mo\", \"tx_count_30d\", \"avg_basket\",\n    \"utilization\", \"support_tickets\", \"order_seq_id\", \"income_bug\",\n]\n\nX_tr = rng.normal(0.0, 1.0, size=(n_tr, 6))\nX_te = rng.normal(0.0, 1.0, size=(n_te, 6))\n\n# Bug 1: auto-increment ID yang bocor masuk fitur (train: 1..700, test: 650..1350)\nid_tr = np.arange(1, n_tr + 1, dtype=float) + rng.normal(0, 15, size=n_tr)\nid_te = np.arange(650, 650 + n_te, dtype=float) + rng.normal(0, 15, size=n_te)\n\n# Bug 2: perubahan konvensi pengisian missing value (train: mean ~ 50, test: 35% baris diisi 0.0!)\ninc_tr = rng.normal(50.0, 10.0, size=n_tr)\ninc_te = rng.normal(50.0, 10.0, size=n_te)\ninc_te[rng.random(n_te) < 0.35] = 0.0\n\nX_tr_full = np.column_stack([X_tr, id_tr, inc_tr])\nX_te_full = np.column_stack([X_te, id_te, inc_te])\n\nX_adv = np.vstack([X_tr_full, X_te_full])\nz_adv = np.r_[np.zeros(n_tr, dtype=int), np.ones(n_te, dtype=int)]\n\ncv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\nadv_clf = RandomForestClassifier(n_estimators=50, max_depth=6, random_state=42)\np_oof_bug = cross_val_predict(adv_clf, X_adv, z_adv, cv=cv, method=\"predict_proba\")[:, 1]\nauc_bug = roc_auc_score(z_adv, p_oof_bug)\n\n# Forensik Permutation Importance pada 1 holdout split untuk mengisolasi fitur pemicu shift\ntr_i, va_i = next(cv.split(X_adv, z_adv))\nadv_clf.fit(X_adv[tr_i], z_adv[tr_i])\nperm = permutation_importance(\n    adv_clf, X_adv[va_i], z_adv[va_i], scoring=\"roc_auc\", n_repeats=8, random_state=42\n)\ntop_idx = np.argsort(-perm.importances_mean)\n\nprint(\"=== 1. Adversarial Validation Gate SEBELUM Perbaikan (z=0 Train vs z=1 Test) ===\")\nprint(f\"Adversarial AUROC (OOF 5-Fold) : {auc_bug:.4f}  --> ALARM MERAH (> 0.70)!\")\nprint(\"Top-4 Fitur Pembeda (Permutation Importance Drop di AUROC):\")\nfor idx in top_idx[:4]:\n    print(f\"  - {feat_names[idx]:16s} : delta_AUROC = {perm.importances_mean[idx]:+.4f} +/- {perm.importances_std[idx]:.4f}\")\n\n# Perbaikan: buang order_seq_id dan perbaiki imputasi income_bug\nX_clean = np.vstack([X_tr, X_te])\np_oof_clean = cross_val_predict(adv_clf, X_clean, z_adv, cv=cv, method=\"predict_proba\")[:, 1]\nauc_clean = roc_auc_score(z_adv, p_oof_clean)\n\nprint(\"\\n=== 2. Adversarial Validation Gate SETELAH Hapus 2 Kolom Bermasalah ===\")\nprint(f\"Adversarial AUROC (OOF 5-Fold) : {auc_clean:.4f}  --> LOLOS GERBANG (~0.50)!\")\n\n# 3. Contoh Covariate Shift Moderat + Density Ratio Weights & Kish Effective Sample Size (ESS)\nX_tr_mod = rng.normal(0.0, 1.0, size=(n_tr, 6))\nX_te_mod = rng.normal(0.0, 1.0, size=(n_te, 6))\nX_te_mod[:, 0] += 0.55  # pergeseran rata-rata moderat pada fitur usia\nX_mod = np.vstack([X_tr_mod, X_te_mod])\np_mod = cross_val_predict(adv_clf, X_mod, z_adv, cv=cv, method=\"predict_proba\")[:, 1]\nauc_mod = roc_auc_score(z_adv, p_mod)\np_tr_clip = np.clip(p_mod[:n_tr], 0.02, 0.98)\nw_imp = (p_tr_clip / (1.0 - p_tr_clip)) * (n_tr / n_te)\nkish_ess = float((w_imp.sum() ** 2) / np.sum(w_imp ** 2))\nprint(\"\\n=== 3. Covariate Shift Moderat -> Density-Ratio Importance Weights ===\")\nprint(f\"Adversarial AUROC Moderat      : {auc_mod:.4f} (perlu monitoring / importance weighting)\")\nprint(f\"Rata-rata bobot w(x) pada Train: {w_imp.mean():.4f} | P95 bobot = {np.percentile(w_imp, 95):.4f}\")\nprint(f\"Kish Effective Sample Size     : {kish_ess:.1f} / {n_tr} ({kish_ess / n_tr:.1%} efisiensi sampel)\")",
